import commentClassification from './comment-classification.mjs';
import referenceIntegrity from './reference-integrity.mjs';
import markdownLinkLabels from './markdown-link-labels.mjs';
import taskLifecycle from './task-lifecycle.mjs';
import warningSuppression from './warning-suppression.mjs';
import filePlacement from './file-placement.mjs';
import squashMergeHistory from './squash-merge-history.mjs';
import claudeMdLength from './claude-md-length.mjs';
import generatedMergeDriver from './generated-merge-driver.mjs';
import sharedConstants from './shared-constants.mjs';
import catalogCompleteness from './catalog-completeness.mjs';
import claudiniteIsolation from './claudinite-isolation.mjs';
import schedulerWorkflowShape from './scheduler-workflow-shape.mjs';
import taskDeclarationShape from './task-declaration-shape.mjs';

// The baseline pack: working discipline, the task lifecycle, and the core
// checks. Declared explicitly like every other pack — no pack is active by
// default. Bootstrap's --init seeds the declaration and the nightly baselining
// backfills it into existing consumers; never fingerprinted (the declaration is
// authoritative — dropping it is a deliberate choice).
export default {
  id: 'basics',
  detect: null,
  marker: null,
  seededByDefault: true,
  prose: 'RULES.md',
  // The consumer-isolation wall rides the barriers mechanism: basics requires
  // the barriers pack and CONTRIBUTES the fixed barrier as manifest data
  // (claudinite-isolation.mjs — pure data, no cross-pack import;
  // pack-independence). git-github carries the git/GitHub side of the task
  // lifecycle (#385). Universal because basics is declared everywhere; the
  // requires closure materializes both declarations alongside it.
  requires: ['barriers', 'git-github'],
  contributes: { barriers: [claudiniteIsolation] },
  rules: [
    commentClassification,
    referenceIntegrity,
    markdownLinkLabels,
    taskLifecycle,
    warningSuppression,
    filePlacement,
    squashMergeHistory,
    claudeMdLength,
    generatedMergeDriver,
    sharedConstants,
    catalogCompleteness,
    // The per-project scheduling conformance guards (scheduled-tasks.md):
    // scheduling is baseline Claudinite discipline — the scheduler workflow and
    // the task-declaration contract are guarded wherever basics is declared
    // (everywhere). Both rules are relevance-first: inert until the repo carries
    // the workflow / a tasks/<name>/task.mjs of its own.
    schedulerWorkflowShape,
    taskDeclarationShape,
  ],
  // The baseline skills — general engineering practice every project's work
  // can call for, whatever its technology — are bundled under skills/ in this
  // pack's own tree and mounted wherever basics is declared (which --init
  // seeds everywhere). The directory listing IS the manifest; when one stops
  // being a baseline activity, move its directory to the pack whose projects
  // need it (#385 moved the git/GitHub and Claudinite-lifecycle skills out).
  //
  // The baseline scheduled task every repo runs — baselining, the per-repo
  // self-refresh — lives in this pack's `tasks/baselining/`, discovered by the
  // scheduler's filesystem scan (engine/scheduler/discover.mjs), not declared
  // here. Being in basics — declared everywhere — makes it universal.
};
=====
// The git/GitHub domain pack: the procedures and owner commands for the
// git/GitHub side of the task lifecycle, bundled as skills
// (skills/git-github-advanced, skills/merge-to-main). No prose and no checks of
// its own (the lifecycle checks stay in basics for now); universal reach comes
// from basics naming it in `requires`, so the closure materializes it into
// every declaration — never seeded directly (#385).
export default {
  id: 'git-github',
  detect: null,
  marker: null,
  prose: null,
  rules: [],
};
=====
// Prose + one environment requirement. Fingerprint: a pubspec.yaml at the repo
// root OR one directory down (a monorepo's app/ or client/ dir) — but never
// deeper, so a stray pubspec.yaml in a nested example/fixture tree can't trip
// detection.
const hasMarkerNearRoot = (ctx, marker) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return parts[parts.length - 1] === marker && parts.length <= 2;
  });

export default {
  id: 'flutter',
  marker: 'pubspec.yaml (at the repo root or one directory down)',
  detect: (ctx) => hasMarkerNearRoot(ctx, 'pubspec.yaml'),
  prose: 'RULES.md',
  rules: [],
  // The Flutter SDK isn't in the Claude Code Web base image, so a cloud session
  // can't run `flutter test` / analyze / golden regen without it. This declares
  // how the environment installs it (aggregated into environment-setup-command.sh) and
  // how the SessionStart check asserts it — see engine/pack_loader/env-requirements.mjs.
  env: {
    label: 'Flutter SDK',
    setup: [
      'if [ ! -x /opt/flutter/bin/flutter ]; then',
      '  git clone --depth 1 -b stable https://github.com/flutter/flutter.git /opt/flutter',
      'fi',
      'ln -sf /opt/flutter/bin/flutter /usr/local/bin/flutter',
      'ln -sf /opt/flutter/bin/dart /usr/local/bin/dart',
      'git config --global --add safe.directory /opt/flutter || true',
      'flutter --version || true',
      'flutter precache || true   # warm host engine artifacts so the first test is fast',
    ].join('\n'),
    probe: 'command -v flutter >/dev/null 2>&1',
  },
};
=====
// Technology pack: Python packaging around an optional heavy/native dependency.
// The mechanical rules about how the optional import itself is written — never
// at module top level, and guarded with a re-raise that names the extra — are
// carried by the mounted `python-optional-deps` skill's check-the-work rules
// (the failure message is the rule, so there is no prose copy to drift from).
// What stays as prose in RULES.md is the residue with no false-positive-free
// signature: which deps belong in the dependency-free base set, the stdlib-
// backend architecture, and the F401 availability-probe suppression.
//
// Fingerprint: a `pyproject.toml` at the repo root OR one directory down (a
// subproject/tool dir) — but never deeper, so a pyproject.toml inside a nested
// fixture/example/vendored tree can't trip detection. (`setup.py`/`setup.cfg`
// are the older equivalent markers; add them here if a consumer predates
// pyproject.toml.)
const hasMarkerNearRoot = (ctx, marker) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return parts[parts.length - 1] === marker && parts.length <= 2;
  });

export default {
  id: 'python',
  marker: 'pyproject.toml (at the repo root or one directory down)',
  detect: (ctx) => hasMarkerNearRoot(ctx, 'pyproject.toml'),
  prose: 'RULES.md',
  rules: [],
};

