  for (const e of errors) process.stderr.write(`! ${e.what} — ${e.fix}\n`);
  for (const [rel, content] of files) {
    writeFileSync(join(canonRoot, rel), content);
    process.stdout.write(`${rel}\n`);
  }
  if (errors.length) process.exit(1);
}

