+    `  <g${at}>`,
+    `    <rect width="${BADGE_SIZE}" height="${BADGE_SIZE}" rx="${CORNER}" fill="url(#${gid(id)})"/>`,
+    `    <path d="${glyph}" fill="none" stroke="${INK}" stroke-width="${STROKE}" stroke-linecap="round" stroke-linejoin="round"/>`,
+    '  </g>',
+  ].join('\n');
