// the per-repo cutover marker during the scheduling rollout (MIGRATION Phase 0.6).
export const CONFIG_KEYS = ['packs', 'rules', 'accept', 'sharedConstants', 'packConfig', 'maintenance', 'claudinite', 'taskScheduler'];

