72	// `process.env.<NAME>` like any other environment variable. No bundle, no parsing,
73	// no engine-side selection. Regenerated from the stub each converge, so the list
74	// tracks the declarations rather than accumulating.
75	export function withDeclaredSecrets(stubText, names = []) {
76	  if (!names.length) return stubText;
77	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
78	  return stubText.replace(/^(\s*GITHUB_TOKEN: \$\{\{ github\.token \}\})$/m, `$1\n${lines}`);
