87	export function convergeSchedulerWorkflow(root, fullName, stubText, secretNames = []) {
88	  const target = withDeclaredSecrets(stubText, secretNames)
89	    .replace(/cron:\s*'[^']*'/, `cron: '${hashedCron(fullName)}'`);
